$.afui.useOSThemes=false;var $loginName;var $password;var requestEncrypt=requestEncrypt;var publicKey=publicKey;var securityToken=securityToken;$(function(){$loginName=$("#loginName");$password=$("#password")});function login(){if(!$loginName.val()){$.afui.toast({message:"账号不能为空!",position:"tc",autoClose:true,type:"success"});return}var a=$password.val();if(!a){$.afui.toast({message:"密码不能为空!",position:"tc",autoClose:true,type:"success"});return}let encryptKey="";let requestEncryptKey="";if("SM4"===requestEncrypt){encryptKey=Sm4Utils.generateSm4HexKey();requestEncryptKey=RSAUtils.encryptHexString(encryptKey,publicKey);a=Sm4Utils.encrypt(a,encryptKey)}else{if("AES"===requestEncrypt){encryptKey=Cryptos.generateAesBase64Key();requestEncryptKey=RSAUtils.encryptBase64String(encryptKey,publicKey);a=Cryptos.encrypt(a,encryptKey)}}$.ajax({url:ctxAdmin+"/login/login",type:"post",headers:{Encrypt:requestEncrypt,"Encrypt-Key":requestEncryptKey},data:{client_id:$("#client_id").val(),redirect_uri:$("#redirect_uri").val(),loginName:$("#loginName").val(),password:a,_csrf_token:securityToken,checkDevice:false},traditional:true,async:false,dataType:"json",success:function(b){if(b.code===1){if(b.obj){setTimeout(function(){window.location=b.obj["homeUrl"]},1000)}else{setTimeout(function(){window.location=ctxMobile},1000)}}else{$.afui.toast({message:b.msg,position:"tc",autoClose:true,type:"warning"})}}})};